import SlideDeck from '../components/presentation/SlideDeck'

export default function WhatisAIAgentandItsOrigin() {
  const slides = [
  {
    "id": 1,
    "title": "Introduction to AI Agents",
    "content": "<h1>What is an AI Agent?</h1><p>An AI Agent is a system that perceives its environment and takes actions to achieve goals. It's an autonomous entity capable of planning, reasoning, and executing tasks to reach a desired outcome.</p><p><strong>Origin:</strong> The concept stems from the field of Artificial Intelligence, drawing from early AI concepts like goal-oriented planning and rational agents.</p>",
    "bgColor": "transparent",
    "customMarkup": "<div style='background-color: #fdfbf7; padding: 20px; border: 3px solid #2d2d2d; border-radius: 255px 15px 225px 15px / 15px 225px 15px 255px; box-shadow: 4px 4px 0px 0px #2d2d2d; font-family: 'Patrick Hand', sans-serif; color: #2d2d2d; line-height: 1.6;'><h2>What is an AI Agent?</h2><p>An AI Agent is a system that perceives its environment and takes actions to achieve goals. It's an autonomous entity capable of planning, reasoning, and executing tasks to reach a desired outcome.</p><p><strong>Origin:</strong> The concept stems from the field of Artificial Intelligence, drawing from early AI concepts like goal-oriented planning and rational agents.</p></div>"
  },
  {
    "id": 2,
    "title": "Agent Architecture",
    "content": "<h1>Key Components of an AI Agent</h1><p>AI Agents typically consist of four core components:</p><ul><li><strong>Perception:</strong> Sensing the environment (e.g., reading data, observing state).</li><li><strong>Reasoning:</strong> Processing information to decide on the best course of action.</li><li><strong>Action:</strong> Executing the plan to interact with the environment.</li><li><strong>Memory:</strong> Storing past experiences to inform future decisions.</li></ul><p>These components work together in a feedback loop to enable autonomous decision-making.</p>",
    "bgColor": "transparent",
    "customMarkup": "<div style='background-color: #fdfbf7; padding: 20px; border: 3px solid #2d2d2d; border-radius: 255px 15px 225px 15px / 15px 225px 15px 255px; box-shadow: 4px 4px 0px 0px #2d2d2d; font-family: 'Patrick Hand', sans-serif; color: #2d2d2d; line-height: 1.6;'><h2>Key Components of an AI Agent</h2><ul><li><strong>Perception:</strong> Sensing the environment (e.g., reading data, observing state).</li><li><strong>Reasoning:</strong> Processing information to decide on the best course of action.</li><li><strong>Action:</strong> Executing the plan to interact with the environment.</li><li><strong>Memory:</strong> Storing past experiences to inform future decisions.</li></ul><p>These components work together in a feedback loop to enable autonomous decision-making.</p></div>"
  },
  {
    "id": 3,
    "title": "Evolution of AI Agents",
    "content": "<h1>Historical Context & Evolution</h1><p>The journey of AI Agents involves several major milestones:</p><ul><li><strong>Early AI (1950s-1970s):</strong> Focus on symbolic reasoning and expert systems.</li><li><strong>The Rise of Goal-Oriented Systems (1980s):</strong> Introduction of search algorithms and planning techniques.</li><li><strong>Modern AI & Machine Learning (2000s-Present):</strong> Emergence of Deep Learning, Reinforcement Learning, and modern LLM-based agents.</li></ul><p>The shift has been from explicitly programmed rules to learning-based, adaptive systems.</p>",
    "bgColor": "transparent",
    "customMarkup": "<div style='background-color: #fdfbf7; padding: 20px; border: 3px solid #2d2d2d; border-radius: 255px 15px 225px 15px / 15px 225px 15px 255px; box-shadow: 4px 4px 0px 0px #2d2d2d; font-family: 'Patrick Hand', sans-serif; color: #2d2d2d; line-height: 1.6;'><h2>Historical Context & Evolution</h2><ul><li><strong>Early AI (1950s-1970s):</strong> Focus on symbolic reasoning and expert systems.</li><li><strong>The Rise of Goal-Oriented Systems (1980s):</strong> Introduction of search algorithms and planning techniques.</li><li><strong>Modern AI & Machine Learning (2000s-Present):</strong> Emergence of Deep Learning, Reinforcement Learning, and modern LLM-based agents.</li></ul><p>The shift has been from explicitly programmed rules to learning-based, adaptive systems.</p></div>"
  }
]

  return <SlideDeck slides={slides} transition="slide-horizontal" />
}
